package com.brightloop.notification;
import jakarta.mail.internet.MimeMessage;import java.nio.charset.StandardCharsets;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.beans.factory.ObjectProvider;import org.springframework.beans.factory.annotation.Value;import org.springframework.mail.javamail.JavaMailSender;import org.springframework.mail.javamail.MimeMessageHelper;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class EmailNotificationService{
 private static final Logger log=LoggerFactory.getLogger(EmailNotificationService.class);private final NotificationRepository repository;private final ObjectProvider<JavaMailSender> mail;private final boolean enabled;public EmailNotificationService(NotificationRepository r,ObjectProvider<JavaMailSender> m,@Value("${brightloop.mail.enabled:false}") boolean enabled){repository=r;mail=m;this.enabled=enabled;}
 @Transactional public void sendOnce(String type,String email,String subject,String body,String eventKey){if(email==null||email.isBlank()||repository.existsByEventKey(eventKey))return;Notification n=repository.save(new Notification(email,type,subject,body,eventKey,enabled?"QUEUED":"DEV_LOGGED"));if(!enabled){log.info("Development email fallback [{}] to {}: {}",type,email,subject);return;}try{JavaMailSender sender=mail.getIfAvailable();if(sender==null)throw new IllegalStateException("SMTP is enabled but JavaMailSender is unavailable");MimeMessage message=sender.createMimeMessage();MimeMessageHelper helper=new MimeMessageHelper(message,false,StandardCharsets.UTF_8.name());helper.setTo(email);helper.setSubject(subject);helper.setText(body,false);sender.send(message);n.status("SENT",null);}catch(Exception ex){n.status("FAILED",ex.getMessage()==null?"SMTP delivery failed":ex.getMessage().substring(0,Math.min(500,ex.getMessage().length())));log.error("Email delivery failed for notification {}",n.getId(),ex);}}
 public void welcome(String email,String name){sendOnce("WELCOME",email,"Welcome to Brightloop","Hi "+name+", your Brightloop account is ready.","welcome:"+email.toLowerCase());}
 public void quotation(String email,String number,String total){sendOnce("QUOTATION",email,"Brightloop quotation "+number,"Your quotation total is INR "+total+". Sign in to review the offer.","quotation:"+number);}
 public void invoice(String email,String number,String total){sendOnce("INVOICE",email,"Brightloop invoice "+number,"Invoice total: INR "+total+". Please review the due date in your portal.","invoice:"+number);}
 public void invoiceReminder(String email,String number,String due){sendOnce("INVOICE",email,"Brightloop invoice "+number,"Your invoice is due on "+due+". Please review your billing portal.","invoice-reminder:"+number);}
 public void payment(String email,String number,String amount){sendOnce("PAYMENT",email,"Brightloop payment receipt "+number,"We received your payment of INR "+amount+".","payment:"+number);}
 public void renewal(String email,String sub,String due){sendOnce("RENEWAL",email,"Upcoming Brightloop renewal","Subscription "+sub+" renews on "+due+".","renewal:"+sub+":"+due);}
 public void overdue(String email,String invoice,String due){sendOnce("OVERDUE",email,"Brightloop invoice overdue","Invoice "+invoice+" was due on "+due+". Please review your billing portal.","overdue:"+invoice+":"+due);}
 public void invoiceDue(String email,String invoice,String due){sendOnce("INVOICE_DUE",email,"Brightloop invoice due soon","Invoice "+invoice+" is due on "+due+". Please review your billing portal.","invoice-due:"+invoice+":"+due);}
}
